class Solution {
    private static final int INF = Integer.MAX_VALUE;
    private static final int[] DR = {1, -1, 0, 0}, DC = {0, 0, 1, -1};
    private int m, n;
    private int[][] grid;

    public int minimumOperations(int[][] grid) {
        // min vertex cover == max matching on the checkerboard bipartite graph (Hopcroft-Karp)
        this.grid = grid;
        m = grid.length;
        n = grid[0].length;
        int total = m * n;
        int[] matchL = new int[total], matchR = new int[total], dist = new int[total];
        int[] it = new int[total], via = new int[total], stack = new int[total + 1], queue = new int[total];
        Arrays.fill(matchL, -1);
        Arrays.fill(matchR, -1);
        List<Integer> left = new ArrayList<>();
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1 && (i + j) % 2 == 0) left.add(i * n + j);
        int matching = 0;
        while (true) {
            int qh = 0, qt = 0;
            for (int u : left) {
                if (matchL[u] == -1) { dist[u] = 0; queue[qt++] = u; }
                else dist[u] = INF;
            }
            boolean found = false;
            while (qh < qt) {
                int u = queue[qh++];
                for (int d = 0; d < 4; d++) {
                    int v = nb(u, d);
                    if (v < 0) continue;
                    int w = matchR[v];
                    if (w == -1) found = true;
                    else if (dist[w] == INF) { dist[w] = dist[u] + 1; queue[qt++] = w; }
                }
            }
            if (!found) break;
            for (int u : left) it[u] = 0;
            for (int root : left) {
                if (matchL[root] != -1) continue;
                int sp = 0;
                stack[sp++] = root;
                while (sp > 0) {
                    int u = stack[sp - 1];
                    if (it[u] == 4) { dist[u] = INF; sp--; continue; }
                    int v = nb(u, it[u]++);
                    if (v < 0) continue;
                    int w = matchR[v];
                    if (w == -1) {
                        via[u] = v;
                        for (int s = 0; s < sp; s++) {
                            int x = stack[s];
                            matchL[x] = via[x];
                            matchR[via[x]] = x;
                        }
                        matching++;
                        break;
                    } else if (dist[w] != INF && dist[w] == dist[u] + 1) {
                        via[u] = v;
                        stack[sp++] = w;
                    }
                }
            }
        }
        return matching;
    }

    private int nb(int u, int d) {
        int r = u / n + DR[d], c = u % n + DC[d];
        if (r < 0 || c < 0 || r >= m || c >= n || grid[r][c] == 0) return -1;
        return r * n + c;
    }
}
